import React, { useState, useEffect } from "react";
import "./Seo.css";
import { useLocation } from "react-router-dom";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faFileLines, faClosedCaptioning, faSearch, faImage } from "@fortawesome/free-solid-svg-icons";

function SEO({ videoThumbnail }) {
  const location = useLocation(); // Get the location object
    const { message, seo, video_upscaling, audio_processing } = location.state || {};

  const [seoMessage, setSeoMessage] = useState(message || "No SEO data received.");

  // Debugging: Log the received results for verification
  useEffect(() => {
    console.log("Received results:", results);
  }, [results]);
  const seoData = results?.seo || {};
  const keywords = seoData.keywords?.length ? seoData.keywords.join(", ") : "No keywords available.";
  const description = seoData.description || "No description available.";
  const title = seoData.title || "No title available.";
  const tags = seoData.tags?.length ? seoData.tags.join(", ") : "No tags available.";

  // Save paths for video upscaling and audio processing
  const videoUpscalingPath = results?.video_upscaling?.output_path || "No video output path available.";
  const audioProcessingPath = results?.audio_processing?.output_path || "No audio output path available.";

  return (
    <div className="seo-app">
      {/* Header Section */}
      <header className="header">
        <h1 className="logo">
          <span className="bold">Channel-</span>
          <span className="highlight">IQ</span>
        </h1>
        <nav className="nav">
          <a href="#clipper">Clipper</a>
          <a href="#seo">SEO</a>
          <a href="#thumbnail">Thumbnail</a>
          <a href="#pricing">Pricing</a>
          <button className="sign-in">Sign in</button>
          <button className="sign-up">Sign up</button>
        </nav>
      </header>

      {/* Main Content Section */}
      <main className="main-content">
        {/* Navigation to Clipper */}
        <button className="clipper-btn">Go to Clipper</button>

        {/* Clip Section */}
        <div className="clip-section">
          {/* Image Preview */}
          <div className="image-preview">
            <img
              src={videoThumbnail || "https://via.placeholder.com/300x300"}
              alt="Video Thumbnail"
              className="preview-image"
            />
          </div>

          {/* Clip Customization */}
          <div className="customize-clip">
            {/* SEO Data Display */}
            <div className="seo-data">
              <div className="seo-box">
                <h2>Keywords</h2>
                <p>{keywords}</p>
              </div>
              <div className="seo-box">
                <h2>Description</h2>
                <p>{description}</p>
              </div>
              <div className="seo-box">
                <h2>Title</h2>
                <p>{title}</p>
              </div>
              <div className="seo-box">
                <h2>Tags</h2>
                <p>{tags}</p>
              </div>
            </div>
          </div>
        </div>
      </main>
    </div>
  );
}

export default SEO;
